  `transaction_type` varchar(50) NOT NULL,
  `card_present` tinyint(1) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_id` (`transaction_id`)
) ENGINE=InnoDB AUTO_INCREMENT=99139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
